(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ShareQRModel=api})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';function validate(s){if(!s||s.version!==1||typeof s.navigationEpoch!=='string'||!/^[A-Za-z0-9_-]{1,64}$/.test(s.navigationEpoch)||typeof s.title!=='string'||s.title.length>160||typeof s.private!=='boolean'||typeof s.url!=='string'||/[\x00-\x20\x7f]/.test(s.url))throw Error('INVALID_CONTEXT');let u;try{u=new URL(s.url)}catch(_){throw Error('INVALID_URL')}if(!['https:','http:'].includes(u.protocol)||u.username||u.password)throw Error('INVALID_URL');if(u.href.length>1024)throw Error('URL_TOO_LONG');return{version:1,navigationEpoch:s.navigationEpoch,title:s.title,url:u.href,private:s.private}}return Object.freeze({validate});});
